#!/usr/bin/env bash
set -euo pipefail

# Drift check for the generated skill routing index. SKILL.md frontmatter
# (description + metadata.scope) is the single source of truth;
# .agents/skills/INDEX.md is generated by scripts/generate-skill-index.mjs and
# must be regenerated (make sync-skill-index) whenever a skill's frontmatter
# changes or a skill is added/removed.
echo "Checking skill routing index sync..."
node scripts/generate-skill-index.mjs --check
echo "Skill index sync check passed"
